app = Flask(__name__)
# 创建一个字典来存储来自 ESP8266 设备的温度和湿度数据
vivarium_data = {
 "vivarium1": {"temperature": 0, "humidity": 0},
 "vivarium2": {"temperature": 0, "humidity": 0},
 "vivarium3": {"temperature": 0, "humidity": 0},
}
@app.route("/")
def index():
 # 使用控制器将控制器中的数据呈现为模板系统，并渲染主页
 return render_template("index.html", vivarium_data=vivarium_data)
@app.route("/update_data///")
def update_data(vivarium, temperature, humidity):
 # 为指定的生态箱更新温湿度数据
 vivarium_data[vivarium]["temperature"] = temperature
 vivarium_data[vivarium]["humidity"] = humidity

 # 返回成功信息
 return "Data updated for vivarium {}: temperature = {}, humidity = {}".format(vivarium, temperature, humidity)
if __name__ == "__main__":
 app.run(host="192.168.1.5", port=5000)

assistant: 这段代码定义了一个 Flask 网络应用，它提供了一个页面，其中包含三个爬虫箱的温度和湿度数据的词典。`index`函数是应用程序主要页面的路径，并使用`render_template`函数将HTML模板`index.html`呈现为带有传递变量的`vivarium_data`词典。`update_data`函数是一条路径，可更新`vivarium_data`词典中特定爬虫箱的温度和湿度数据。它可通过发送请求到`/update_data/<vivarium>/<temperature>/<humidity>`URL访问，其中`<vivarium>`是要更新的爬虫箱的名称，`<temperature>`和`<humidity>`是相应的新的温度和湿度值。
运行脚本时，网络应用将托管在指定的IP地址（`192.168.1.5`）和端口（`5000`）上。要访问应用程序的主页面，可以在网络浏览器中访问`http://192.168.1.5:5000/`。要更新爬虫箱的数据，可以使用适当的参数向`update_data`路径发送请求。例如，要使用`25`度和`50`湿度更新`vivarium1`的数据，则可以将请求发送到`http://192.168.1.5:5000/update_data/vivarium1/25/50`。

