const express = require('express');
const mysql = require('mysql');
const bodyParser = require('body-parser');
const dotenv = require('dotenv');
const app = express();
// 从 .env 文件中加载 MySQL 配置
dotenv.config();
// 配置 MySQL 连接
const connection = mysql.createConnection({
  host: process.env.MYSQL_HOST,
  user: process.env.MYSQL_USER,
  password: process.env.MYSQL_PASSWORD,
  database: process.env.MYSQL_DATABASE,
});
// 连接到 MySQL
connection.connect((err) => {
  if (err) {
    console.error('error connecting: ' + err.stack);
    return;
  }
  console.log('connected as id ' + connection.threadId);
});
// 配置解析请求体的中间件
app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());
// 定义接收对象数组的 API 端点
app.post('/objects', (req, res) => {
  const objects = req.body.objects;
  // 将每个对象插入到 MySQL 数据库中
  objects.forEach((obj) => {
    const query = `INSERT INTO objects (id, name, created_date, created_by) VALUES (${obj.id}, '${obj.name}', '${obj.createdDate}', '${obj.createdBy}')`;
    connection.query(query, (err, results) => {
      if (err) {
        console.error(err);
        res.status(500).send('Error storing objects in MySQL');
        return;
      }
      console.log(`Stored object with ID ${obj.id}`);
    });
  });
  res.status(200).send('Objects stored in MySQL');
});
// 启动服务器
const PORT = process.env.PORT || 8080;
app.listen(PORT, () => {
  console.log(`App listening on port ${PORT}`);
});
```

通过使用外部的 `.env` 文件，您可以将配置与代码分离，并通过在 `.env` 文件中更改设置，轻松地在不同的环境（如开发、预发布、生产）之间切换。

