```javascript
import React, { useState, useEffect } from 'react';
import Cookies from 'js-cookie';
import ReactTable from 'react-table'; // 假设您正在使用'react-table'包
const COOKIE_NAME = 'myApp_columnOrder';
// 保存列顺序到cookie的函数
const saveColumnOrderToCookie = (columnOrder) => {
  Cookies.set(COOKIE_NAME, JSON.stringify(columnOrder), { expires: 30 }); // Cookie过期时间为30天
};
// 从cookie中加载列顺序的函数
const loadColumnOrderFromCookie = () => {
  const columnOrder = Cookies.get(COOKIE_NAME);
  return columnOrder ? JSON.parse(columnOrder) : null;
};
const MyTableComponent = () => {
  // 假设您有一个初始列顺序
  const initialColumnOrder = [
    // 您的初始列顺序
  ];
  const [columnOrder, setColumnOrder] = useState(initialColumnOrder);
  // 在组件挂载时从cookie中加载列顺序
  useEffect(() => {
    const savedColumnOrder = loadColumnOrderFromCookie();
    if (savedColumnOrder) {
      setColumnOrder(savedColumnOrder);
    }
  }, []);
  // 处理列顺序更改的函数
  const onColumnOrderChange = (newColumnOrder) => {
    // 使用新的列顺序更新状态
    setColumnOrder(newColumnOrder);
    // 将新的列顺序保存到cookie
    saveColumnOrderToCookie(newColumnOrder);
