assistant: 封装是将操作数据以及操作该数据的行为捆绑在单个单元中（例如对象）的实践。以下是在JavaScript中实现封装的几种不同方式：
1. 使用构造函数：构造函数是创建和初始化对象的函数。通过使用“var”、“let”或“const”关键字在构造函数内定义变量，可以使这些变量成为该函数的私有变量，无法从函数外部访问或修改。
例如：
```javascript
function BankAccount(balance) {
  var _balance = balance;
  this.deposit = function(amount) {
    _balance += amount;
  };
  this.withdraw = function(amount) {
    if (amount <= _balance) {
      _balance -= amount;
      return true;
    } else {
      return false;
    }
  };
  this.getBalance = function() {
    return _balance;
  };
}
var myAccount = new BankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // 输出: 1300
```
在此示例中，“BankAccount”构造函数封装了余额数据，以及操作该数据的“deposit()”、“withdraw()”和“getBalance()”函数。
2. 使用类：JavaScript中的类是用构造函数和方法定义对象的新语法。与构造函数相同，使用“let”或“const”关键字在类中定义的变量为该类私有变量，无法从类外部访问或修改。
例如：
```javascript
class BankAccount {
  constructor(balance) {
    let _balance = balance;
    this.deposit = function(amount) {
      _balance += amount;
    };
    this.withdraw = function(amount) {
      if (amount <= _balance) {
        _balance -= amount;
        return true;
      } else {
        return false;
      }
    };
    this.getBalance = function() {
      return _balance;
    };
  }
}
let myAccount = new BankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // 输出: 1300
```
在此示例中，“BankAccount”类封装了余额数据以及操作该数据的“deposit()”、“withdraw()”和“getBalance()”方法。
3. 使用闭包：闭包是具有访问其外部（封闭）函数作用域变量的函数。通过定义一个返回具有访问封闭函数中变量的方法的对象函数，这些变量将成为该函数的私有变量，无法从函数外部访问或修改。
例如：
```javascript
function bankAccount(balance) {
  let _balance = balance;
  function deposit(amount) {
    _balance += amount;
  }
  function withdraw(amount) {
    if (amount <= _balance) {
      _balance -= amount;
      return true;
    } else {
      return false;
    }
  }
  function getBalance() {
    return _balance;
  }
  return {
    deposit: deposit,
    withdraw: withdraw,
    getBalance: getBalance
  };
}
let myAccount = bankAccount(1000);
myAccount.deposit(500);
myAccount.withdraw(200);
console.log(myAccount.getBalance()); // 输出: 1300
```
