```csharp
public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    if (env.IsDevelopment())
    {
        app.UseDeveloperExceptionPage();
    }
    app.UseHttpsRedirection();
    app.UseRouting();
    // 添加自定义中间件以进行 URL 重写
    app.Use(async (context, next) =>
    {
        var originalBody = context.Response.Body;
        using var newBody = new MemoryStream();
        context.Response.Body = newBody;
        await next();
        newBody.Seek(0, SeekOrigin.Begin);
        if (context.Response.ContentType != null && context.Response.ContentType.Contains("text/html", StringComparison.OrdinalIgnoreCase))
        {
            var content = await new StreamReader(newBody).ReadToEndAsync();
            var parser = new HtmlParser();
            var document = await parser.ParseDocumentAsync(content);
            // 重写资产 URL 指向代理端点
            foreach (var img in document.Images)
            {
                img.Source = RewriteUrl(img.Source, context);
            }
            foreach (var link in document.QuerySelectorAll("link[href]"))
            {
                link.SetAttribute("href", RewriteUrl(link.GetAttribute("href"), context));
            }
            foreach (var script in document.Scripts)
            {
                script.Source = RewriteUrl(script.Source, context);
            }
            content = document.DocumentElement.OuterHtml;
            context.Response.ContentLength = content.Length;
            await context.Response.WriteAsync(content);
        }
        else
        {
            await newBody.CopyToAsync(originalBody);
        }
    });
    // 添加 YARP 中间件
    app.UseReverseProxy();
    app.UseAuthorization();
    app.UseEndpoints(endpoints =>
    {
        endpoints.MapControllers();
    });
}
private string RewriteUrl(string url, HttpContext context)
{
    if (Uri.IsWellFormedUriString(url, UriKind.Absolute))
    {
        var uriBuilder = new UriBuilder(url)
        {
            Scheme = context.Request.Scheme,
            Host = context.Request.Host.Host,
            Port = context.Request.Host.Port.GetValueOrDefault(-1)
        };
        return uriBuilder.ToString();
    }
    return url;
}
