```csharp
public void ConfigureServices(IServiceCollection services)
{
    services.AddControllers();

    // 添加自定义授权策略
    services.AddAuthorization(options =>
    {
        options.AddPolicy("LocalOnly", policy =>
        {
            policy.RequireAssertion(context =>
                context.Resource is HttpContext httpContext && httpContext.Connection.RemoteIpAddress != null &&
                (httpContext.Connection.RemoteIpAddress.Equals(httpContext.Connection.LocalIpAddress) ||
