namespace MyApi.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class MyController : ControllerBase
    {
        // 此操作可以从任何位置访问
        [HttpGet("public")]
        public IActionResult GetPublicData()
        {
            return Ok("This is public data.");
        }
        // 此操作仅可从本地访问
