        options.AddPolicy("PayrollEditor", policy => policy.RequireClaim("scope", "https://contoso.com/payroll/write"));
        options.AddPolicy("PayrollAdmin", policy => policy.RequireClaim("scope", "https://contoso.com/payroll/admin"));
    });
    // 添加 MVC
