import { VaultSnapshot, PoolSnapshot, DailyPoolSnapshot, MonthlyPoolSnapshot, YearlyPoolSnapshot } from '../generated/schema'
import { BigDecimal, BigInt, log } from '@graphprotocol/graph-ts'
export function handleVaultSnapshot(event: VaultSnapshot): void {
  // 获取同一Uniswap V3池的前一日、前一月、前一年的PoolSnapshot事件
  let now = event.block.timestamp.toI32()
  let day = 86400
  let month = 30 * day
  let year = 365 * day
  let pool = event.params.pool.toHex()
  let previousDailySnapshot = DailyPoolSnapshot.load(pool + '-' + ((now / day) * day).toString())
  let previousMonthlySnapshot = MonthlyPoolSnapshot.load(pool + '-' + ((now / month) * month).toString())
  let previousYearlySnapshot = YearlyPoolSnapshot.load(pool + '-' + ((now / year) * year).toString())
  // 如果没有之前的每日、每月或每年快照，则创建新快照。
  if (!previousDailySnapshot) {
    previousDailySnapshot = new DailyPoolSnapshot(pool + '-' + ((now / day) * day).toString())
    previousDailySnapshot.currentPrice = event.params.currentPrice
    previousDailySnapshot.poolTotalSupply = event.params.poolTotalSupply
    previousDailySnapshot.totalSupply = event.params.totalSupply
    previousDailySnapshot.timestamp = event.block.timestamp
    previousDailySnapshot.save()
  }
  if (!previousMonthlySnapshot) {
    previousMonthlySnapshot = new MonthlyPoolSnapshot(pool + '-' + ((now / month) * month).toString())
    previousMonthlySnapshot.currentPrice = event.params.currentPrice
    previousMonthlySnapshot.poolTotalSupply = event.params.poolTotalSupply
    previousMonthlySnapshot.totalSupply = event.params.totalSupply
    previousMonthlySnapshot.timestamp = event.block.timestamp
    previousMonthlySnapshot.save()
  }
  if (!previousYearlySnapshot) {
    previousYearlySnapshot = new YearlyPoolSnapshot(pool + '-' + ((now / year) * year).toString())
    previousYearlySnapshot.currentPrice = event.params.currentPrice
    previousYearlySnapshot.poolTotalSupply = event.params.poolTotalSupply
    previousYearlySnapshot.totalSupply = event.params.totalSupply
    previousYearlySnapshot.timestamp = event.block.timestamp
    previousYearlySnapshot.save()
  }

  // 在早期和后期快照中计算流动性提供者对池的份额
  let earlierDailyShareOfPool = previousDailySnapshot.totalSupply.toBigDecimal().div(previousDailySnapshot.poolTotalSupply.toBigDecimal())
  let laterDailyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  let earlierMonthlyShareOfPool = previousMonthlySnapshot.totalSupply.toBigDecimal().div(previousMonthlySnapshot.poolTotalSupply.toBigDecimal())
  let laterMonthlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  let earlierYearlyShareOfPool = previousYearlySnapshot.totalSupply.toBigDecimal().div(previousYearlySnapshot.poolTotalSupply.toBigDecimal())
  let laterYearlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  // 计算每日、每月和每年快照的APY
  let dailyAPY = pow(laterDailyShareOfPool.div(earlierDailyShareOfPool), BigDecimal.fromString('365')).minus(BigDecimal.fromString('1')).times(BigDecimal.fromString('100'))
  let monthlyAPY = pow(laterMonthlyShareOfPool.div(earlierMonthlyShareOfPool), BigDecimal.fromString('12')).minus(BigDecimal.fromString('1')).times(BigDecimal.fromString('100'))
  let yearlyAPY = pow(laterYearlyShareOfPool.div(earlierYearlyShareOfPool), BigDecimal.fromString('1')).minus(BigDecimal.fromString('1')).times(BigDecimal.fromString('100'))
}
