为更新已存在的先前的每日、每月和每年快照，您可以通过它们的 ID（由池地址和时间戳组成）加载它们，并使用新数据更新其属性。这是一段更新的代码，展示了如何进行此操作：

```csharp
import { VaultSnapshot, PoolSnapshot, DailyPoolSnapshot, MonthlyPoolSnapshot, YearlyPoolSnapshot } from '../generated/schema'
import { BigDecimal, BigInt, log } from '@graphprotocol/graph-ts'
export function handleVaultSnapshot(event: VaultSnapshot): void {
  // 获取同一Uniswap V3 池的每日、每月和每年PoolSnapshot事件
  let now = event.block.timestamp.toI32()
  let day = 86400
  let month = 30 * day
  let year = 365 * day
  let pool = event.params.pool.toHex()
  let dailySnapshot = DailyPoolSnapshot.load(pool + '-' + ((now / day) * day).toString())
  let monthlySnapshot = MonthlyPoolSnapshot.load(pool + '-' + ((now / month) * month).toString())
  let yearlySnapshot = YearlyPoolSnapshot.load(pool + '-' + ((now / year) * year).toString())
  // 如果没有先前的每日、每月或每年快照，则创建新的快照
  if (!dailySnapshot) {
    dailySnapshot = new DailyPoolSnapshot(pool + '-' + ((now / day) * day).toString())
    dailySnapshot.timestamp = event.block.timestamp
  }
  if (!monthlySnapshot) {
    monthlySnapshot = new MonthlyPoolSnapshot(pool + '-' + ((now / month) * month).toString())
    monthlySnapshot.timestamp = event.block.timestamp
  }
  if (!yearlySnapshot) {
    yearlySnapshot = new YearlyPoolSnapshot(pool + '-' + ((now / year) * year).toString())
    yearlySnapshot.timestamp = event.block.timestamp
  }

  // 计算提供流动性的用户在两个快照的池份额
  let earlierDailyShareOfPool = dailySnapshot.totalSupply.toBigDecimal().div(dailySnapshot.poolTotalSupply.toBigDecimal())
  let laterDailyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  let earlierMonthlyShareOfPool = monthlySnapshot.totalSupply.toBigDecimal().div(monthlySnapshot.poolTotalSupply.toBigDecimal())
  let laterMonthlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  let earlierYearlyShareOfPool = yearlySnapshot.totalSupply.toBigDecimal().div(yearlySnapshot.poolTotalSupply.toBigDecimal())
  let laterYearlyShareOfPool = event.params.totalSupply.toBigDecimal().div(event.params.poolTotalSupply.toBigDecimal())
  // 计算提供流动性的用户在两个快照之间获得的费用
  let dailyFeesEarned = event.params.totalFees.toBigDecimal().times(laterDailyShareOfPool.minus(earlierDailyShareOfPool))
  let monthlyFeesEarned = event.params.totalFees.toBigDecimal().times(laterMonthlyShareOfPool.minus(earlierMonthlyShareOfPool))
  let yearlyFeesEarned = event.params.totalFees.toBigDecimal().times(laterYearlyShareOfPool.minus(earlierYearlyShareOfPool))
  // 使用新数据更新每日、每月和每年快照
  dailySnapshot.poolTotalSupply = event.params.poolTotalSupply
  dailySnapshot.totalSupply = event.params.totalSupply
  dailySnapshot.totalFees = event.params.totalFees
  dailySnapshot.currentPrice = event.params.currentPrice
  dailySnapshot.feesEarned = dailySnapshot.feesEarned.plus(dailyFeesEarned)
  dailySnapshot.save()
```

