  data.forEach(hit => {
    const resultElement = document.createElement('div');
    resultElement.classList.add('result');
    resultElement.innerHTML = `

${truncateText(hit.page_contents || '', 500)}

      ${hit.links}
    `;
    fragment.appendChild(resultElement);
  });
  container.appendChild(fragment);
}

function handleSearch(event) {
  event.preventDefault();
  const searchInput = document.getElementById('search-input');
  const searchQuery = searchInput.value.trim();
  if (searchQuery) {
    makeAPICall(searchQuery).then(data => {
      if (data) {
        sessionStorage.setItem('searchResults', JSON.stringify(data));
        const resultsContainer = document.getElementById('results-container');
        displayResults(resultsContainer, data.hits);
      }
    });
  }
}

window.addEventListener('DOMContentLoaded', () => {
  const searchForm = document.getElementById('search-form');
  if (searchForm) {
    searchForm.addEventListener('submit', handleSearch);
  } else {
    console.error('页面找不到search-form元素');
  }
  const results = JSON.parse(sessionStorage.getItem('searchResults'));
  if (results && results.hits.length > 0) {
    // 在页面上显示结果
    const resultsContainer = document.getElementById('results-container');
    if (resultsContainer) {
      displayResults(resultsContainer, results.hits);
    }
  } else {
    // 显示未找到结果的信息
    const noResultsElement = document.createElement('div');
    noResultsElement.textContent = '没有找到结果。';
    const resultsContainer = document.getElementById('results-container');
    if (resultsContainer) {
      resultsContainer.appendChild(noResultsElement);
    }
  }
});
```

以下是更改说明：

1. 将`displayResults()`函数移到了`window.addEventListener('DOMContentLoaded', () => {`块外，以避免嵌套。
2. 移除了`results`检查中的额外的`Object.values()`循环。

