  p_responsibility_name VARCHAR2(240) := 'YOUR_RESPONSIBILITY_NAME';
  p_request_group_name VARCHAR2(240) := 'YOUR_REQUEST_GROUP_NAME';
  p_concurrent_program_name VARCHAR2(240) := 'YOUR_CONCURRENT_PROGRAM_NAME';
BEGIN
  -- 授予必要的角色和责任
  DBMS_XS_SESSION.GRANT_SYSTEM_PRIVILEGE('CONNECT', p_username);
  FND_USER_PKG.ADDRESP(p_username, p_responsibility_name, 'A');

  -- 授予请求组的访问权限
  FND_REQUEST_GRP_UTIL_PVT.Add_Request_Group(p_request_group_name, p_responsibility_name, SYSDATE + 365, 'N');

  -- 授予并发程序的访问权限
  FND_REQUEST_GRP_UTIL_PVT.ADD_PROGRAM(p_request_group_name, p_concurrent_program_name, p_responsibility_name, SYSDATE + 365, 'N', 'Y', 'Y');

