const axios = require('axios');
const qs = require('qs');
const Airtable = require('airtable');
const base = new Airtable({ apiKey: 'YOUR_API_KEY' }).base('YOUR_BASE_ID');
const client_id = 'your-client-id';
const client_secret = 'your-client-secret';
const access_token_url = 'https://[your-visual-url]/IONAPI/oauth2/token';
const api_url = 'https://[your-visual-url]/IONAPI/Custom/MyApp/LaborTicketData';

async function getAccessToken() {
  const authOptions = {
    method: 'POST',
    url: access_token_url,
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    data: qs.stringify({
      grant_type: 'client_credentials',
      client_id: client_id,
      client_secret: client_secret,
      scope: 'Production'
    })
  };
  const authResponse = await axios(authOptions);
  const access_token = authResponse.data.access_token;
  return access_token;
}

async function getLaborTickets(access_token, dateFrom, dateTo) {
  const headers = {
    'Authorization': 'Bearer ' + access_token
  };
  const options = {
    method: 'GET',
    url: api_url,
    headers: headers,
    params: {
      "TicketCriteria": {
        "TicketStatus": "All",
        "DateFrom": dateFrom,
        "DateTo": dateTo
      }
    }
  };
  const response = await axios(options);
  const laborTickets = response.data.LaborTicketData.LaborTicket;
  return laborTickets;
}

function saveLaborTicketsToAirtable(laborTickets) {
  for (let i = 0; i < laborTickets.length; i++) {
    const laborTicket = laborTickets[i];
    base('Labor Tickets').create({
      "Labor Ticket Number": laborTicket.LaborTicketNumber,
      "Work Order Number": laborTicket.WorkOrderNumber,
      "Operation": laborTicket.WorkCenterOperation,
      "Resource": laborTicket.Resource,
      "Start Time": laborTicket.StartDateTime,
      "End Time": laborTicket.EndDateTime
    }, function(err, record) {
      if (err) {
        console.error(err);
        return;
      }
      console.log('Record created:', record.getId());
    });
  }
}

async function main() {
  try {
    const access_token = await getAccessToken();
    const laborTickets = await getLaborTickets(access_token, '2022-01-01', '2022-02-28');
    saveLaborTicketsToAirtable(laborTickets);
  } catch (error) {
    console.error(error);
  }
}

main();
```

该代码将逻辑分成三个函数：`getAccessToken`、`getLaborTickets` 和 `saveLaborTicketsToAirtable`。`getAccessToken` 函数使用 OAuth2 客户端凭据流程获取访问令牌，而 `getLaborTickets` 函数使用访问令牌从 Infor Visual API 中检索劳动工票数据。`saveLaborTicketsToAirtable` 函数将劳动工票数据保存到 Airtable 数据库中。

`main` 函数是脚本的入口点，按顺序调用三个函数，并处理可能发生的任何错误。通过将代码分为不同函数，代码变得更模块化、更易于理解，每个函数可以独立重用或测试。

